            "task_class": "legal",
            "risk_category": "legal_posture",
            "need_count": 9,
        }
        assert task_spec["task_class"] == "legal"
        assert task_spec["risk_category"] == "legal_posture"
        assert task_spec["need_count"] >= 9

    def test_preflight_triage_model_configured(self):
        """Preflight triage uses google:gemini-2.0-flash."""
        preflight = {"model": "google:gemini-2.0-flash", "qpd_leader": 7.0}
        assert "gemini" in preflight["model"]
        assert preflight["qpd_leader"] >= 7.0

    def test_strategy_planner_model_configured(self):
        """Strategy planner uses local:codestral:22b."""
        planner = {"model": "local:codestral:22b", "qpd_leader": 6.7}
        assert "codestral" in planner["model"]
        assert planner["qpd_leader"] >= 6.5

    def test_agentic_coder_model_configured(self):
        """Agentic coder uses cowork-skill with haiku model."""
        coder = {
            "model": "claude-haiku-4-5-20251001",
            "skill": "cowork-skill",
        }
        assert "haiku" in coder["model"]
        assert coder["skill"] == "cowork-skill"

    def test_qa_route_uses_deepseek(self):
        """Independent QA route uses deepseek:deepseek-v4-flash."""
        qa_route = {
            "model": "deepseek:deepseek-v4-flash",
            "samples": 14,
            "type": "explore",
        }
        assert "deepseek" in qa_route["model"]
        assert qa_route["samples"] >= 14

