        """QA panel includes llama and deepseek models."""
        panel = ["local:llama3.2:3b", "deepseek:deepseek-v4-flash"]
        assert any("llama" in m for m in panel)
        assert any("deepseek" in m for m in panel)
        assert len(panel) >= 2

    def test_legal_gate_owner_only(self):
        """Legal gate enforces owner-only for licensing/registration changes."""
        legal_gate = {
            "gating_rule": "owner_only",
            "triggers": [
                "licensing",
                "registration",
                "custody",
                "transmission",
                "advice",
                "secret_management",
            ],
        }
        assert legal_gate["gating_rule"] == "owner_only"
        assert len(legal_gate["triggers"]) >= 5

