            "auto_merge_target": "orchestrator/dev",
            "after_steps": ["tests", "verify", "judge"],
            "production_release": "batch_train",
        }
        assert release_config["auto_merge_target"] == "orchestrator/dev"
        assert all(s in release_config["after_steps"] for s in ["tests", "verify"])


